SELECT CAST(COUNT(DISTINCT CASE WHEN p.drug = 'GLP-1' AND EXTRACT(HOUR FROM c.charttime) BETWEEN 0 AND 47 THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS proportion_first_48h, CAST(COUNT(DISTINCT CASE WHEN p.drug = 'GLP-1' AND EXTRACT(HOUR FROM c.charttime) BETWEEN 48 AND 59 THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS proportion_final_12h, CAST(COUNT(DISTINCT CASE WHEN p.drug = 'GLP-1' THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS proportion_total FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN chartevents c ON a.subject_id = c.subject_id AND a.hadm_id = c.hadm_id WHERE p.gender = 'F' AND p.anchor_age >= 64 AND c.itemid IN (SELECT itemid FROM d_items WHERE category = 'Drug') AND (EXTRACT(HOUR FROM c.charttime) BETWEEN 0 AND 47 OR EXTRACT(HOUR FROM c.charttime) BETWEEN 48 AND 59);